CREATE OR REPLACE FUNCTION public.append_relationship_identity_decision(p_org uuid, p_actor uuid, p_a jsonb, p_b jsonb, p_decision text, p_evidence text[], p_summary text, p_candidate text, p_aliases jsonb, p_note text, p_request uuid, p_expected_head uuid, p_previous uuid, p_versions jsonb, p_founder boolean DEFAULT false)
 RETURNS relationship_identity_decisions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior public.relationship_identity_decisions; result public.relationship_identity_decisions; head uuid; ref jsonb; found_org uuid; private boolean:=false; pair text;
begin
 if not exists(select 1 from public.organisation_members where organisation_id=p_org and user_id=p_actor and lower(role::text) in ('owner','admin')) then raise exception 'Authorised reviewer required';end if;
 if p_founder and not exists(select 1 from public.organisation_members where organisation_id=p_org and user_id=p_actor and lower(role::text)='owner') then raise exception 'Protected reviewer required';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_org::text,5805));
 select * into result from public.relationship_identity_decisions where organisation_id=p_org and idempotency_key=p_request;
 if found then
 if result.actor_user_id<>p_actor or result.source_ref_a<>p_a or result.source_ref_b<>p_b or result.decision<>p_decision or result.candidate_revision<>p_candidate or result.note is distinct from p_note then raise exception 'Receipt payload mismatch';end if;
 return result;
 end if;
 select id into head from public.relationship_identity_decisions where organisation_id=p_org order by sequence desc limit 1;
 if head is distinct from p_expected_head then raise exception 'Identity history changed; refresh';end if;
 -- Lock the exact reviewed sources through append; the hash contains no exposed source text.
 for ref in select value from jsonb_array_elements(jsonb_build_array(p_a,p_b)) loop
 if ref->>'table' not in ('inbox_items','growth_targets','acquisition_items','founder_research_records') then raise exception 'Invalid source';end if;
 execute format('select organisation_id from public.%I where id=$1 for share',ref->>'table') into found_org using (ref->>'id')::uuid;
 if found_org is distinct from p_org then raise exception 'Source outside tenant';end if;
 end loop;
 if p_versions is null or p_versions is distinct from public.identity_decision_source_versions(p_org,p_actor,p_a,p_b,p_founder) then raise exception 'Source evidence changed; refresh';end if;
 pair:=(p_a->>'table')||':'||(p_a->>'id')||'|'||(p_b->>'table')||':'||(p_b->>'id');
 if not (p_evidence @> array[(p_a->>'table')||':'||(p_a->>'id'),(p_b->>'table')||':'||(p_b->>'id')]) then raise exception 'Reviewed source evidence required';end if;
 select * into prior from public.relationship_identity_decisions where organisation_id=p_org and pair_key=pair order by revision desc limit 1;
 if prior.id is distinct from p_previous then raise exception 'Decision revision changed; refresh';end if;
 for ref in select value from jsonb_array_elements(jsonb_build_array(p_a,p_b)) loop
 if ref->>'table' not in ('inbox_items','growth_targets','acquisition_items','founder_research_records') then raise exception 'Invalid source';end if;
 execute format('select organisation_id from public.%I where id=$1',ref->>'table') into found_org using (ref->>'id')::uuid;
 if found_org is distinct from p_org then raise exception 'Source outside tenant';end if;
 if ref->>'table'='founder_research_records' then private:=true;end if;
 end loop;
 private:=private or coalesce(prior.founder_only,false) or p_founder;
 if private and not p_founder then raise exception 'Protected evidence unavailable';end if;
 insert into public.relationship_identity_decisions(organisation_id,source_ref_a,source_ref_b,decision,reviewed_evidence_ids,evidence_summary,actor_user_id,revision,note,supersedes_decision_id,candidate_revision,alias_bindings,founder_only,idempotency_key)
 values(p_org,p_a,p_b,p_decision,p_evidence,p_summary,p_actor,coalesce(prior.revision,0)+1,p_note,prior.id,p_candidate,p_aliases,private,p_request) returning * into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.apply_acquisition_action(p_organisation_id uuid, p_item_id uuid, p_actor_user_id uuid, p_expected_status text, p_action text, p_new_status text, p_outcome text, p_note text, p_idempotency_key uuid, p_marks_actioned boolean)
 RETURNS SETOF acquisition_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 v_item public.acquisition_items%rowtype;
 v_destination text;
 v_personal boolean;
 v_url_parts text[];
 v_host text;
 v_path text;
 v_direct_discussion boolean;
begin
 select * into v_item from public.acquisition_items
 where id = p_item_id and organisation_id = p_organisation_id for update;
 if not found then raise exception using errcode = 'P0002', message = 'acquisition_item_not_found'; end if;

 if exists (select 1 from public.acquisition_item_events where acquisition_item_id=p_item_id and idempotency_key=p_idempotency_key and action<>p_action) then raise exception 'idempotency_key_reused'; end if;
 if exists (select 1 from public.acquisition_item_events where acquisition_item_id = p_item_id and idempotency_key = p_idempotency_key) then
 return query select * from public.acquisition_items where id = p_item_id and organisation_id = p_organisation_id;
 return;
 end if;
 if v_item.status <> p_expected_status then raise exception using errcode = '40001', message = 'acquisition_item_changed'; end if;

 v_personal := coalesce(p_action in ('personal_responded','personal_engaged','personal_capacity_check','personal_signup','personal_subscriber'),false);
 if v_personal then
 v_url_parts := regexp_match(v_item.source_url,
 '^https://([A-Za-z0-9.-]+)(:443)?(/[^?#[:space:]\\]*)([?][^#[:space:]\\]*)?(#[^[:space:]\\]*)?$', 'i');
 v_host := regexp_replace(lower(v_url_parts[1]), '^(www|m)[.]', '');
 v_path := v_url_parts[3];
 v_direct_discussion := coalesce(case
 when v_host in ('reddit.com','old.reddit.com','new.reddit.com') then v_path ~ '/comments/[^/]+'
 when v_host = 'facebook.com' then v_path ~ '/(posts|videos|reel)/[^/]+'
 or (v_path ~ '/(permalink|story)[.]php$' and v_url_parts[4] ~ '[?&]story_fbid=[^&#]+')
 when v_host = 'instagram.com' then v_path ~ '^/(p|reel)/[^/]+'
 when v_host in ('threads.net','threads.com') then v_path ~ '/post/[^/]+'
 when v_host in ('x.com','twitter.com') then v_path ~ '/status/[^/]+'
 when v_host = 'linkedin.com' then v_path ~ '/posts/[^/]+|/feed/update/urn:li:'
 when v_host = 'tiktok.com' then v_path ~ '/video/[^/]+'
 else false end, false);
 if v_item.source_engine <> 'root_health_personal' or v_item.record_type not in ('personal_opportunity','social_opportunity')
 or nullif(v_item.source_record_id,'') is null or not v_direct_discussion
 or concat_ws(' ', v_item.metadata->>'lane', v_item.metadata->>'opportunity_type',
 v_item.metadata->>'content_type', v_item.metadata->>'sheet_tab',
 v_item.engine_state->>'opportunity_type') ~* 'search.?demand|article|blog|partner|referr'
 or v_item.metadata->'engine_safety'->'public_context' is distinct from 'true'::jsonb
 or v_item.metadata->'engine_safety'->'consumer_outreach' is distinct from 'false'::jsonb
 or v_item.metadata->'engine_safety'->'health_targeting' is distinct from 'false'::jsonb
 or v_item.metadata->'engine_safety'->'verified_direct_discussion' is distinct from 'true'::jsonb
 or nullif(trim(coalesce(v_item.metadata->>'original_post',v_item.metadata->>'post_text','')),'') is null
 then raise exception 'unverified_personal_signal'; end if;
 if exists(select 1 from public.acquisition_item_events where acquisition_item_id=p_item_id and action=p_action) then raise exception 'personal_milestone_already_recorded'; end if;
 if (p_action='personal_responded' and (v_item.status not in ('new','reviewing','accepted') or p_new_status<>'actioned' or p_outcome<>'Responded'))
 or (p_action='personal_engaged' and (v_item.status<>'actioned' or p_new_status<>'engaged' or p_outcome<>'Engaged'))
 or (p_action='personal_capacity_check' and (v_item.status<>'engaged' or p_new_status<>'engaged' or p_outcome<>'Capacity Check'))
 or (p_action='personal_signup' and (v_item.status<>'engaged' or p_new_status<>'engaged' or p_outcome<>'Signup'))
 or (p_action='personal_subscriber' and (v_item.status<>'engaged' or p_new_status<>'converted' or p_outcome<>'Subscriber'))
 or p_outcome is null then raise exception 'invalid_personal_milestone'; end if;
 if p_action='personal_signup' and not exists(select 1 from public.acquisition_item_events where acquisition_item_id=p_item_id and action='personal_capacity_check')
 or p_action='personal_subscriber' and not exists(select 1 from public.acquisition_item_events where acquisition_item_id=p_item_id and action='personal_signup') then raise exception 'preceding_personal_milestone_required'; end if;
 end if;
 v_destination := case p_action
 when 'prepare_outreach' then '/dashboard/growth/pipeline' when 'route_outreach' then '/dashboard/growth/pipeline'
 when 'create_content_draft' then '/dashboard/brainstorm' when 'route_campaign' then '/dashboard/campaigns/new'
 when 'route_publishing' then '/dashboard/publishing' when 'route_responses' then '/dashboard/responses' else null end;
 if v_destination is not null and p_new_status <> 'actioned' then raise exception 'invalid_handoff_status'; end if;
 if p_new_status = 'actioned' and v_destination is null and not v_personal then raise exception 'handoff_required'; end if;
 update public.acquisition_items set
 metadata = case when v_destination is null then metadata else coalesce(metadata,'{}'::jsonb) || jsonb_build_object('handoff',
 jsonb_build_object('action',p_action,'destination',v_destination,'recorded_at',now(),'actor_user_id',p_actor_user_id,'idempotency_key',p_idempotency_key)) end,
 status = p_new_status,
 current_action = p_action,
 actioned_at = case when p_marks_actioned then coalesce(actioned_at, now()) else actioned_at end,
 outcome = coalesce(p_outcome, outcome),
 outcome_at = case when p_outcome is not null then now() else outcome_at end,
 owner_user_id = coalesce(owner_user_id, p_actor_user_id),
 updated_at = now()
 where id = p_item_id and organisation_id = p_organisation_id;

 insert into public.acquisition_item_events (
 organisation_id, acquisition_item_id, actor_user_id, action,
 previous_status, new_status, outcome, note, idempotency_key
 ) values (
 p_organisation_id, p_item_id, p_actor_user_id, p_action,
 v_item.status, p_new_status, p_outcome, p_note, p_idempotency_key
 );
 return query select * from public.acquisition_items where id = p_item_id and organisation_id = p_organisation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_lifecycle_repairs(p_organisation_id uuid, p_expected_revision bigint, p_repairs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 version bigint;
 repair jsonb;
 patch jsonb;
 target public.growth_targets%rowtype;
 applied integer := 0;
 affected integer;
 item_id uuid;
begin
 if p_organisation_id is null
 or jsonb_typeof(p_repairs) is distinct from 'array' then
 raise exception 'invalid_reconciliation';
 end if;

 insert into public.lifecycle_revisions(organisation_id)
 values(p_organisation_id)
 on conflict do nothing;

 select revision
 into version
 from public.lifecycle_revisions
 where organisation_id = p_organisation_id
 for update;

 if version is distinct from p_expected_revision then
 return jsonb_build_object(
 'stale', true,
 'applied', 0
 );
 end if;

 for repair in
 select value
 from jsonb_array_elements(p_repairs)
 loop
 patch := repair->'patch';
 item_id := (repair->>'id')::uuid;

 if jsonb_typeof(patch) is distinct from 'object'
 or patch = '{}'::jsonb then
 raise exception 'invalid_patch';
 end if;

 if repair->>'table' = 'growth_targets' then

 if item_id is null then
 if patch - array[
 'target_name',
 'company',
 'linkedin_identity',
 'linkedin_url',
 'stage',
 'status',
 'last_action_at',
 'source_type',
 'source_record_id'
 ] <> '{}'::jsonb
 or patch->>'source_type' is distinct from 'lifecycle_connection_accepted'
 or patch->>'linkedin_identity' is null then
 raise exception 'invalid_insert';
 end if;

 target := jsonb_populate_record(
 null::public.growth_targets,
 patch
 );

 insert into public.growth_targets(
 organisation_id,
 target_name,
 company,
 linkedin_identity,
 linkedin_url,
 stage,
 status,
 last_action_at,
 source_type,
 source_record_id
 )
 values(
 p_organisation_id,
 target.target_name,
 target.company,
 target.linkedin_identity,
 target.linkedin_url,
 target.stage,
 target.status,
 target.last_action_at,
 target.source_type,
 target.source_record_id
 );

 else
 if patch - array[
 'stage',
 'status',
 'last_action_at',
 'reply_status',
 'replied_at',
 'deal_stage'
 ] <> '{}'::jsonb then
 raise exception 'invalid_growth_patch';
 end if;

 select *
 into target
 from public.growth_targets
 where id = item_id
 and organisation_id = p_organisation_id
 for update;

 if not found then
 raise exception 'target_not_found';
 end if;

 target := jsonb_populate_record(
 target,
 patch
 );

 update public.growth_targets
 set
 stage = target.stage,
 status = target.status,
 last_action_at = target.last_action_at,
 reply_status = target.reply_status,
 replied_at = target.replied_at,
 deal_stage = target.deal_stage
 where id = item_id
 and organisation_id = p_organisation_id;
 end if;

 elsif repair->>'table' = 'inbox_items'
 and item_id is not null then

 if patch - array[
 'response_state',
 'follow_up_at'
 ] <> '{}'::jsonb then
 raise exception 'invalid_inbox_patch';
 end if;

 update public.inbox_items
 set
 response_state =
 case
 when patch ? 'response_state'
 then patch->>'response_state'
 else response_state
 end,
 follow_up_at =
 case
 when patch ? 'follow_up_at'
 then (patch->>'follow_up_at')::timestamptz
 else follow_up_at
 end
 where id = item_id
 and organisation_id = p_organisation_id;

 else
 raise exception 'invalid_repair_table';
 end if;

 get diagnostics affected = row_count;

 if affected <> 1 then
 raise exception 'repair_target_not_found';
 end if;

 applied := applied + 1;
 end loop;

 return jsonb_build_object(
 'stale', false,
 'applied', applied
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_relationship_workspace_action(p_org uuid, p_actor uuid, p_refs jsonb, p_kind text, p_founder boolean, p_workspace uuid, p_revision bigint, p_key uuid, p_action text, p_details jsonb, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare w public.relationship_workspaces; prior public.relationship_activity_events; ref jsonb; ids uuid[]; valid boolean; private boolean; has_operational boolean; stamp timestamptz:=clock_timestamp(); ev uuid; model uuid; version_no bigint; task_id uuid; actual timestamptz;begin
 -- Serialize only workspace metadata writes within this tenant, including lazy creation.
 perform pg_advisory_xact_lock(hashtextextended(p_org::text,742));
 if not exists(select 1 from public.organisation_members where organisation_id=p_org and user_id=p_actor and lower(role::text) in ('owner','admin','manager')) then raise exception 'Workspace actor is not authorised for tenant';end if;
 if p_actor is null or p_key is null or p_request is null or jsonb_typeof(p_request)<>'object' or p_details is null or jsonb_typeof(p_details)<>'object' then raise exception 'Invalid action';end if;
 if p_refs is null or jsonb_typeof(p_refs)<>'array' or jsonb_array_length(p_refs)=0 or jsonb_array_length(p_refs)>1000 then raise exception 'Existing relationship evidence required';end if;
 select * into prior from public.relationship_activity_events where organisation_id=p_org and idempotency_key=p_key;
 if found then
 if prior.actor<>p_actor or prior.request is distinct from p_request then raise exception 'idempotency_key_reused';end if;
 if prior.founder_only and not p_founder then raise exception 'Founder access required';end if;
 return jsonb_build_object('workspaceId',prior.workspace_id,'duplicate',true);
 end if;
 private:=false;has_operational:=false;
 for ref in select * from jsonb_array_elements(p_refs) loop
 if ref->>'table' not in ('inbox_items','growth_targets','acquisition_items','founder_research_records') then raise exception 'Unsupported source';end if;
 execute format('select exists(select 1 from public.%I where organisation_id=$1 and id=$2)',ref->>'table') into valid using p_org,(ref->>'id')::uuid;
 if not valid then raise exception 'Source does not belong to tenant';end if;
 if ref->>'table'='founder_research_records' then private:=true;else has_operational:=true;end if;
 end loop;
 if private and not p_founder then raise exception 'Founder access required';end if;
 select array_agg(distinct l.workspace_id) into ids from public.relationship_source_links l where l.organisation_id=p_org and exists(select 1 from jsonb_array_elements(p_refs) r where r->>'table'=l.source_table and (r->>'id')::uuid=l.source_id);
 if coalesce(cardinality(ids),0)>1 then raise exception 'Duplicate relationship workspaces require explicit review';end if;
 if p_workspace is not null and cardinality(ids)=1 and p_workspace<>ids[1] then raise exception 'Relationship changed';end if;
 if cardinality(ids)=1 or p_workspace is not null then
 select * into w from public.relationship_workspaces where organisation_id=p_org and id=coalesce(p_workspace,ids[1]) for update;
 if not found then raise exception 'Relationship not found';end if;
 if w.founder_only and not p_founder and not exists(select 1 from public.relationship_source_links l where l.organisation_id=p_org and l.workspace_id=w.id and l.source_table<>'founder_research_records' and exists(select 1 from jsonb_array_elements(p_refs) r where r->>'table'=l.source_table and (r->>'id')::uuid=l.source_id)) then raise exception 'Founder access required';end if;
 if w.entity_kind<>p_kind then raise exception 'Person/company identity conflict';end if;
 if p_revision is null or w.revision<>p_revision then raise exception 'Relationship changed; reload';end if;
 else
 if p_revision is not null then raise exception 'Relationship changed';end if;
 insert into public.relationship_workspaces(organisation_id,entity_kind,founder_only,created_by) values(p_org,p_kind,not has_operational,p_actor) returning * into w;
 end if;
 for ref in select * from jsonb_array_elements(p_refs) loop
 insert into public.relationship_source_links(organisation_id,workspace_id,source_table,source_id,linked_by) values(p_org,w.id,ref->>'table',(ref->>'id')::uuid,p_actor) on conflict do nothing;
 end loop;
 -- Shared identity stays accessible; each saved artifact retains its own protected scope.
 if w.founder_only and has_operational then update public.relationship_workspaces set founder_only=false where id=w.id;end if;
 actual:=case when p_details->>'timeChoice'='now' then stamp else nullif(p_details->>'occurredAt','')::timestamptz end;
 if actual>stamp then raise exception 'Activity time cannot be in the future';end if;
 if p_action='note' then
 if p_details->>'noteType' is null or p_details->>'noteType' not in ('Observation','Strategic thought','Meeting note','Commitment','Reminder','Idea') or nullif(btrim(p_details->>'message'),'') is null then raise exception 'Typed note required';end if;
 elsif p_action='activity' then
 if p_details->>'activityType' is null or p_details->>'activityType' not in ('emailed','linkedin_contacted','called','meeting','note') or p_details->>'confirmed'<>'true' then raise exception 'Confirm manual activity';end if;
 elsif p_action='retention' then
 if p_details->>'retention' is null or p_details->>'retention' not in ('active','archived','stale') then raise exception 'Invalid retention';end if;
 update public.relationship_workspaces set retention=p_details->>'retention' where id=w.id;
 elsif p_action='company_link' then
 if exists(select 1 from public.relationship_workspaces where organisation_id=p_org and id=(p_details->>'companyId')::uuid and founder_only) then
 if not p_founder then raise exception 'Founder access required';end if;private:=true;
 end if;
 update public.relationship_workspaces set related_company_id=(p_details->>'companyId')::uuid where organisation_id=p_org and id=w.id;
 elsif p_action='task_created' then
 if not exists(select 1 from public.organisation_members where organisation_id=p_org and user_id=(p_details->>'owner')::uuid) then raise exception 'Task owner must belong to tenant';end if;
 insert into public.relationship_tasks(organisation_id,workspace_id,founder_only,task,due_at,owner_user_id,source,created_by) values(p_org,w.id,private,p_details->>'task',nullif(p_details->>'dueAt','')::timestamptz,(p_details->>'owner')::uuid,coalesce(nullif(p_details->>'source',''),'User-created relationship task'),p_actor) returning id into task_id;
 elsif p_action='task_state' then
 if p_details->>'status' is null or p_details->>'status' not in ('open','done','cancelled') then raise exception 'Invalid task state';end if;
 if exists(select 1 from public.relationship_tasks where organisation_id=p_org and workspace_id=w.id and id=(p_details->>'taskId')::uuid and founder_only) then
 if not p_founder then raise exception 'Founder access required';end if;private:=true;
 end if;
 update public.relationship_tasks set status=p_details->>'status',updated_at=stamp where organisation_id=p_org and workspace_id=w.id and id=(p_details->>'taskId')::uuid returning id into task_id;
 if task_id is null then raise exception 'Task not found';end if;
 elsif p_action='value' then
 if jsonb_typeof(p_details->'calculation') is distinct from 'object' then raise exception 'Calculation required';end if;
 else raise exception 'Unsupported relationship action';end if;
 insert into public.relationship_activity_events(organisation_id,workspace_id,actor,founder_only,activity_type,note_type,message,occurred_at,idempotency_key,request,details)
 values(p_org,w.id,p_actor,private,p_action,case when p_action='note' then p_details->>'noteType' end,p_details->>'message',case when p_action in ('note','activity') then actual else stamp end,p_key,p_request,p_details||jsonb_build_object('taskId',task_id,'previousRetention',w.retention)) returning id into ev;
 if p_action='value' then
 model:=nullif(p_details->'calculation'->'input'->>'pricingModelId','')::uuid;
 if coalesce((p_details->>'saveTenantDefault')::boolean,false) then
 if private then raise exception 'Founder-protected pricing cannot become a shared tenant default';end if;
 if not exists(select 1 from public.organisation_members where organisation_id=p_org and user_id=p_actor and lower(role::text) in ('owner','admin')) then raise exception 'Only owner/admin may change tenant pricing';end if;
 select coalesce(max(version),0)+1 into version_no from public.relationship_pricing_models where organisation_id=p_org;
 update public.relationship_pricing_models set is_default=false where organisation_id=p_org and is_default;
 insert into public.relationship_pricing_models(organisation_id,version,config,created_by) values(p_org,version_no,(p_details->'calculation'->'input')-array['totalEmployees','eligibleEmployees','expectedQuantity','expectedRate','revenueBasis','potentialManual','expectedManual','oneOffPotential','oneOffExpected','services','basis','quantitySource','pricingModelId','pricingVersion'],p_actor) returning id into model;
 end if;
 insert into public.relationship_value_assessments(organisation_id,workspace_id,founder_only,pricing_model_id,input,result,actor,event_id) values(p_org,w.id,private,model,(p_details->'calculation'->'input')||case when version_no is not null then jsonb_build_object('pricingModelId',model,'pricingVersion',version_no) else '{}'::jsonb end,jsonb_set(p_details->'calculation','{input}',(p_details->'calculation'->'input')||case when version_no is not null then jsonb_build_object('pricingModelId',model,'pricingVersion',version_no) else '{}'::jsonb end),p_actor,ev);
 end if;
 update public.relationship_workspaces set revision=revision+1,updated_at=stamp where organisation_id=p_org and id=w.id;
 return jsonb_build_object('workspaceId',w.id,'duplicate',false);
end $function$

CREATE OR REPLACE FUNCTION public.backfill_linkedin_cadence(p_organisation_id uuid, p_expected_revision bigint, p_repairs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare version bigint; repair jsonb; target public.growth_targets%rowtype; applied integer:=0;
begin
 insert into public.lifecycle_revisions(organisation_id) values(p_organisation_id) on conflict do nothing;
 select revision into version from public.lifecycle_revisions where organisation_id=p_organisation_id for update;
 if version is distinct from p_expected_revision then raise exception 'stale_cadence_report'; end if;
 if jsonb_typeof(p_repairs) is distinct from 'array' then raise exception 'invalid_cadence_repairs'; end if;
 perform set_config('root.cadence_backfill','1',true);
 for repair in select * from jsonb_array_elements(p_repairs) loop
 if repair->>'id' is null then
 if repair->'patch'->>'source_type' is distinct from 'lifecycle_connection_accepted'
 or not exists(select 1 from public.inbox_items where organisation_id=p_organisation_id and id=(repair->'patch'->>'source_record_id')::uuid and kind='connection_accepted' and platform='linkedin' and status='replied')
 or exists(select 1 from public.growth_targets where organisation_id=p_organisation_id and linkedin_identity=repair->'patch'->>'linkedin_identity') then raise exception 'cadence_creation_evidence_changed'; end if;
 insert into public.growth_targets(organisation_id,target_name,linkedin_identity,linkedin_url,stage,status,last_action_at,first_outbound_at,first_outbound_text,source_type,source_record_id)
 values(p_organisation_id,repair->'patch'->>'target_name',repair->'patch'->>'linkedin_identity',repair->'patch'->>'linkedin_url',repair->'patch'->>'stage','active',(repair->'patch'->>'last_action_at')::timestamptz,(repair->'patch'->>'first_outbound_at')::timestamptz,repair->'patch'->>'first_outbound_text','lifecycle_connection_accepted',repair->'patch'->>'source_record_id');
 applied:=applied+1;continue;
 end if;
 select * into target from public.growth_targets where organisation_id=p_organisation_id and id=(repair->>'id')::uuid for update;
 if not found or target.status not in ('active','waiting') or target.replied_at is not null or coalesce(target.reply_status,'') not in ('','no_reply') then raise exception 'cadence_evidence_changed'; end if;
 if (repair->'patch') - array['stage','status','first_outbound_at','first_outbound_text'] <> '{}'::jsonb
 or repair->'patch'->>'stage' not in ('day3_followup','day7_parity','day14_insight','day28_relevance','day42_close','parked')
 or nullif(repair->'patch'->>'first_outbound_text','') is null
 or (repair->'patch'->>'first_outbound_at')::timestamptz > now()
 or (target.first_outbound_at is not null and target.first_outbound_at is distinct from (repair->'patch'->>'first_outbound_at')::timestamptz)
 then raise exception 'invalid_cadence_anchor'; end if;
 if repair->'patch'->>'stage'='parked' and target.manual_completion->>'stage' is distinct from 'day42_close' then raise exception 'final_close_not_confirmed'; end if;
 update public.growth_targets set stage=repair->'patch'->>'stage',status=case when repair->'patch'->>'stage'='parked' then 'parked' else status end,
 first_outbound_at=coalesce(first_outbound_at,(repair->'patch'->>'first_outbound_at')::timestamptz),
 first_outbound_text=coalesce(first_outbound_text,repair->'patch'->>'first_outbound_text')
 where organisation_id=p_organisation_id and id=target.id;
 applied:=applied+1;
 end loop;
 perform set_config('root.cadence_backfill','0',true);
 return jsonb_build_object('applied',applied);
end; $function$

CREATE OR REPLACE FUNCTION public.dismiss_social_responses(p_organisation_id uuid, p_ids uuid[], p_actor_user_id uuid, p_reason text, p_idempotency_key uuid)
 RETURNS SETOF inbox_items
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare item public.inbox_items; stamp timestamptz := clock_timestamp();
begin
 if p_organisation_id is null or p_actor_user_id is null or p_idempotency_key is null or
 coalesce(cardinality(p_ids),0) not between 1 and 100 or array_position(p_ids,null) is not null or
 (p_reason is not null and p_reason not in ('Promotional solicitation','Spam / irrelevant','Not an opportunity','Other')) then
 raise exception 'invalid_dismissal';
 end if;
 -- Lock deterministically; invalid/mixed-tenant batches never partially apply.
 perform id from public.inbox_items where organisation_id=p_organisation_id and id=any(p_ids) order by id for update;
 if (select count(*) from public.inbox_items where organisation_id=p_organisation_id and id=any(p_ids)
 and platform in ('instagram','facebook','threads','reddit','tiktok','linkedin')
 and kind in ('comment','dm','mention','reaction')
 and coalesce(response_state,'') not in ('converted','closed_or_lost'))
 <> (select count(distinct id) from unnest(p_ids) id) then
 raise exception using errcode='P0002',message='social_response_not_found';
 end if;
 for item in select * from public.inbox_items where organisation_id=p_organisation_id and id=any(p_ids) order by id loop
 if (item.response_state is distinct from 'no_reply_needed' or item.status is distinct from 'archived') and
 not exists(select 1 from public.response_item_events where inbox_item_id=item.id and idempotency_key=p_idempotency_key) then
 update public.inbox_items set response_state='no_reply_needed',status='archived',follow_up_at=null,response_updated_at=stamp
 where organisation_id=p_organisation_id and id=item.id;
 insert into public.response_item_events(organisation_id,inbox_item_id,actor_user_id,action,previous_state,new_state,note,idempotency_key)
 values(p_organisation_id,item.id,p_actor_user_id,'dismissed',item.response_state,'no_reply_needed',p_reason,p_idempotency_key);
 end if;
 end loop;
 return query select * from public.inbox_items where organisation_id=p_organisation_id and id=any(p_ids);
end; $function$

CREATE OR REPLACE FUNCTION public.guard_founder_record_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if tg_op='UPDATE' and (new.organisation_id<>old.organisation_id or new.id<>old.id or new.created_by<>old.created_by) then raise exception 'Founder identity ownership is immutable'; end if;
 if tg_op='UPDATE' and old.linked_acquisition_item_id is not null and new.linked_acquisition_item_id is distinct from old.linked_acquisition_item_id then raise exception 'Acquisition link is immutable once set'; end if;
 if new.linked_acquisition_item_id is not null and not exists(select 1 from public.acquisition_items where id=new.linked_acquisition_item_id and organisation_id=new.organisation_id) then raise exception 'Invalid tenant acquisition link'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_manual_email_recovery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare receipt jsonb;
begin
 if new.status in ('dispatching','accepted') then
 select manual_completion into receipt from public.inbox_items where organisation_id=new.organisation_id and id=new.inbox_item_id for update;
 if receipt is not null then raise exception 'manual_completion_prevents_repeat_delivery'; end if;
 end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.guard_relationship_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare valid boolean; begin
 if tg_op='UPDATE' then raise exception 'Relationship source links are immutable'; end if;
 if new.source_table not in ('inbox_items','growth_targets','acquisition_items','founder_research_records') then raise exception 'Unsupported source';end if;
 execute format('select exists(select 1 from public.%I where organisation_id=$1 and id=$2)',new.source_table) into valid using new.organisation_id,new.source_id;
 if not valid then raise exception 'Source does not belong to tenant';end if;
 return new;end $function$

CREATE OR REPLACE FUNCTION public.guard_relationship_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if tg_op='UPDATE' and (new.id<>old.id or new.organisation_id<>old.organisation_id or new.entity_kind<>old.entity_kind or new.created_by<>old.created_by) then raise exception 'Relationship ownership is immutable';end if;
 if tg_op='UPDATE' and new.founder_only is distinct from old.founder_only and (new.founder_only or not exists(select 1 from public.relationship_source_links where organisation_id=new.organisation_id and workspace_id=new.id and source_table<>'founder_research_records')) then raise exception 'Only operational evidence may open a Founder workspace';end if;
 if new.related_company_id is not null and (new.entity_kind<>'person' or not exists(select 1 from public.relationship_workspaces where organisation_id=new.organisation_id and id=new.related_company_id and entity_kind='company')) then raise exception 'Invalid company relationship';end if;
 return new;end $function$

CREATE OR REPLACE FUNCTION public.handle_new_user_create_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
 workspace_name text;
 workspace_slug text;
 new_org_id uuid;
begin
 -- If this user already has a membership, do nothing
 if exists (
 select 1
 from public.organisation_members
 where user_id = new.id
 ) then
 return new;
 end if;

 workspace_name :=
 coalesce(
 nullif(trim(new.raw_user_meta_data ->> 'organisation_name'), ''),
 nullif(trim(new.raw_user_meta_data ->> 'business_name'), ''),
 nullif(trim(new.raw_user_meta_data ->> 'full_name'), ''),
 nullif(trim(split_part(coalesce(new.email, ''), '@', 1)), ''),
 'New Workspace'
 );

 workspace_slug :=
 lower(
 regexp_replace(workspace_name, '[^a-zA-Z0-9]+', '-', 'g')
 );

 workspace_slug := trim(both '-' from workspace_slug);

 if workspace_slug = '' then
 workspace_slug := 'workspace';
 end if;

 workspace_slug := workspace_slug || '-' || substring(replace(gen_random_uuid()::text, '-', '') from 1 for 8);

 insert into public.organisations (
 id,
 owner_id,
 name,
 slug,
 brand_name,
 brand_primary_color,
 brand_secondary_color,
 created_at
 )
 values (
 gen_random_uuid(),
 new.id,
 workspace_name,
 workspace_slug,
 workspace_name,
 '#00A676',
 '#006B4A',
 now()
 )
 returning id into new_org_id;

 insert into public.organisation_members (
 organisation_id,
 user_id,
 role,
 created_at
 )
 values (
 new_org_id,
 new.id,
 'owner',
 now()
 );

 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.identity_decision_source_versions(p_org uuid, p_actor uuid, p_a jsonb, p_b jsonb, p_founder boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ref jsonb; row_data jsonb; result jsonb:='{}';
begin
 if not exists(select 1 from public.organisation_members where organisation_id=p_org and user_id=p_actor and lower(role::text) in ('owner','admin')) then raise exception 'Authorised reviewer required';end if;
 for ref in select value from jsonb_array_elements(jsonb_build_array(p_a,p_b)) loop
 if ref->>'table' not in ('inbox_items','growth_targets','acquisition_items','founder_research_records') then raise exception 'Invalid source';end if;
 if ref->>'table'='founder_research_records' and (not p_founder or not exists(select 1 from public.organisation_members where organisation_id=p_org and user_id=p_actor and lower(role::text)='owner')) then raise exception 'Protected evidence unavailable';end if;
 execute format('select to_jsonb(t) from public.%I t where id=$1 and organisation_id=$2',ref->>'table') into row_data using (ref->>'id')::uuid,p_org;
 if row_data is null then raise exception 'Source outside tenant';end if;
 result:=result||jsonb_build_object((ref->>'table')||':'||(ref->>'id'),md5(row_data::text));
 end loop;return result;
end $function$

CREATE OR REPLACE FUNCTION public.increment_org_post_usage(p_organisation_id uuid)
 RETURNS TABLE(allowed boolean, posts_used integer, posts_limit integer)
 LANGUAGE plpgsql
AS $function$
declare
 v_plan_record public.organisation_plans%rowtype;
 v_period_start date;
 v_current_usage public.organisation_post_usage%rowtype;
begin
 -- Determine current month start (e.g. 2025-12-01)
 v_period_start := date_trunc('month', now())::date;

 -- Look up the organisation's plan
 select *
 into v_plan_record
 from public.organisation_plans
 where organisation_id = p_organisation_id;

 if not found then
 -- No plan found: default to basic 8 posts/month for safety
 v_plan_record.posts_per_month := 8;
 end if;

 -- Ensure a usage row exists for this period
 insert into public.organisation_post_usage (
 organisation_id,
 period_start,
 posts_used
 )
 values (
 p_organisation_id,
 v_period_start,
 0
 )
 on conflict (organisation_id, period_start) do nothing;

 -- Lock and read the current usage row
 select *
 into v_current_usage
 from public.organisation_post_usage
 where organisation_id = p_organisation_id
 and period_start = v_period_start
 for update;

 if not found then
 -- Should not happen because of the insert, but safety fallback
 v_current_usage.posts_used := 0;
 end if;

 -- Check if adding one more post would exceed the limit
 if (v_current_usage.posts_used + 1) > v_plan_record.posts_per_month then
 -- Over limit: do NOT increment, just return the current usage and limit
 allowed := false;
 posts_used := v_current_usage.posts_used;
 posts_limit := v_plan_record.posts_per_month;
 return;
 end if;

 -- Under limit: increment usage
 update public.organisation_post_usage
 set
 posts_used = posts_used + 1,
 last_post_at = now(),
 updated_at = now()
 where id = v_current_usage.id
 returning posts_used
 into posts_used;

 allowed := true;
 posts_limit := v_plan_record.posts_per_month;

 return;
end;
$function$

CREATE OR REPLACE FUNCTION public.preserve_manual_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if tg_op='INSERT' then
 if current_user in ('anon','authenticated') and new.manual_completion is not null then raise exception 'manual_receipt_requires_authorized_service'; end if;
 return new;
 end if;
 if current_user in ('anon','authenticated') and new.manual_completion is distinct from old.manual_completion then raise exception 'manual_receipt_requires_authorized_service'; end if;
 if old.manual_completion is not null then
 if new.manual_completion is null then new.manual_completion:=old.manual_completion; end if;
 if tg_table_name='inbox_items' then
 if new.status is distinct from 'archived' then new.status:=old.status; end if;
 new.last_replied_at:=old.last_replied_at; new.last_reply_text:=old.last_reply_text;
 new.contacted_at:=old.contacted_at; new.follow_up_at:=null;
 if new.response_state is null or new.response_state in ('needs_reply','follow_up','waiting_for_human') or (old.response_state in ('converted','closed_or_lost','meeting') and new.response_state not in ('converted','closed_or_lost','meeting')) then new.response_state:=old.response_state; end if;
 elsif new.manual_completion is not distinct from old.manual_completion then
 if new.stage is distinct from old.stage and new.stage is distinct from 'parked' and not (current_user not in ('anon','authenticated') and current_setting('root.cadence_backfill',true)='1') then raise exception 'manual_completion_prevents_cadence_regression'; end if;
 new.last_action_at := greatest(old.last_action_at,new.last_action_at);
 end if;
 end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.promote_acquisition_target(p_organisation_id uuid, p_item_id uuid, p_actor uuid, p_key uuid, p_action text, p_note text, p_updated_at timestamp with time zone, p_target jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 item public.acquisition_items%rowtype;
 target public.growth_targets%rowtype;
 matches uuid[];
 created boolean := false;
 linked uuid;
 existing_linkedin text;
begin
 if p_actor is null or p_key is null or p_action is null or p_action not in ('prepare_outreach','route_outreach')
 or jsonb_typeof(p_target) is distinct from 'object'
 or p_target - array['target_name','company','role_title','email','linkedin_identity','linkedin_url','notes'] <> '{}'::jsonb
 or nullif(trim(p_target->>'target_name'),'') is null
 or (nullif(p_target->>'linkedin_identity','') is null and nullif(p_target->>'email','') is null)
 then raise exception 'invalid_promotion'; end if;

 -- Includes legacy/import writers which do not take an advisory identity lock.
 -- No provider calls occur while this short transaction holds the lock.
 lock table public.growth_targets in share row exclusive mode;
 select * into item from public.acquisition_items
 where id=p_item_id and organisation_id=p_organisation_id for update;
 if not found then raise exception 'acquisition_item_not_found'; end if;
 if item.record_type not in ('b2b_lead','partner_opportunity') then raise exception 'unsupported_type'; end if;
 if item.status not in ('accepted','actioned','nurture') then raise exception 'acquisition_item_changed'; end if;
 if exists(select 1 from public.acquisition_item_events where acquisition_item_id=p_item_id and idempotency_key=p_key and action<>p_action)
 then raise exception 'idempotency_key_reused'; end if;

 linked := nullif(item.metadata->'handoff'->>'target_id','')::uuid;
 if linked is not null and not exists(select 1 from public.growth_targets where id=linked and organisation_id=p_organisation_id)
 then raise exception 'linked_target_identity_conflict'; end if;
 select array_agg(id) into matches from public.growth_targets
 where organisation_id=p_organisation_id and (
 id=linked or acquisition_item_id=p_item_id
 or (source_type=item.source_engine and source_record_id=item.source_record_id)
 or (p_target->>'linkedin_identity' is not null and linkedin_identity=p_target->>'linkedin_identity')
 or (p_target->>'linkedin_identity' is not null and replace(regexp_replace(regexp_replace(
 lower(split_part(split_part(linkedin_url,'?',1),'#',1)),'^https?://(www\.)?',''), '/$',''),'/comm/in/','/in/')=p_target->>'linkedin_identity')
 or (p_target->>'email' is not null and lower(trim(email))=lower(p_target->>'email'))
 or (item.person is not null and p_target->>'company' is not null and lower(trim(target_name))=lower(trim(item.person))
 and lower(trim(company))=lower(trim(p_target->>'company')))
 );
 if coalesce(cardinality(matches),0)>1 then raise exception 'ambiguous_target_identity'; end if;
 if cardinality(matches)=1 then
 select * into target from public.growth_targets where id=matches[1] and organisation_id=p_organisation_id for update;
 existing_linkedin := coalesce(target.linkedin_identity,replace(regexp_replace(regexp_replace(
 lower(split_part(split_part(target.linkedin_url,'?',1),'#',1)),'^https?://(www\.)?',''), '/$',''),'/comm/in/','/in/'));
 if (existing_linkedin is not null and p_target->>'linkedin_identity' is not null and existing_linkedin<>p_target->>'linkedin_identity')
 or (target.email is not null and p_target->>'email' is not null and lower(trim(target.email))<>lower(p_target->>'email'))
 or (item.person is not null and target.target_name is not null and lower(trim(target.target_name))<>lower(trim(item.person))
 and lower(trim(target.target_name)) is distinct from lower(trim(target.company)))
 then raise exception 'target_identity_conflict'; end if;
 if linked=target.id and exists(select 1 from public.acquisition_item_events where organisation_id=p_organisation_id
 and acquisition_item_id=p_item_id and idempotency_key=(item.metadata->'handoff'->>'idempotency_key')::uuid
 and action=item.metadata->'handoff'->>'action') then
 return jsonb_build_object('targetId',target.id,'created',false,'duplicate',true,'item',to_jsonb(item));
 end if;
 end if;
 if item.updated_at is distinct from p_updated_at then raise exception 'acquisition_item_changed'; end if;
 if target.id is null then
 insert into public.growth_targets(organisation_id,target_name,company,role_title,email,linkedin_identity,linkedin_url,
 notes,stage,status,source_type,source_record_id,acquisition_item_id,owner_user_id)
 values(p_organisation_id,p_target->>'target_name',p_target->>'company',p_target->>'role_title',p_target->>'email',
 p_target->>'linkedin_identity',p_target->>'linkedin_url',p_target->>'notes','connection','active',
 item.source_engine,item.source_record_id,item.id,coalesce(item.owner_user_id,p_actor)) returning * into target;
 created := true;
 else
 -- Fill missing identity/context only; never reset a reused target's cadence.
 update public.growth_targets set email=coalesce(email,p_target->>'email'),
 linkedin_identity=coalesce(linkedin_identity,p_target->>'linkedin_identity'),
 linkedin_url=coalesce(linkedin_url,p_target->>'linkedin_url'),
 company=coalesce(company,p_target->>'company'),role_title=coalesce(role_title,p_target->>'role_title'),
 acquisition_item_id=coalesce(acquisition_item_id,item.id),owner_user_id=coalesce(owner_user_id,item.owner_user_id,p_actor)
 where id=target.id and organisation_id=p_organisation_id;
 end if;
 perform public.apply_acquisition_action(p_organisation_id,p_item_id,p_actor,item.status,p_action,'actioned',null,p_note,p_key,true);
 -- Retrying a legacy handoff receipt still upgrades its destination to a real target.
 update public.acquisition_items set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{handoff}',
 jsonb_build_object('action',p_action,'destination','/dashboard/growth/pipeline','target_id',target.id,
 'recorded_at',now(),'actor_user_id',p_actor,'idempotency_key',p_key)), updated_at=now()
 where id=p_item_id and organisation_id=p_organisation_id returning * into item;
 return jsonb_build_object('targetId',target.id,'created',created,'duplicate',not created,'item',to_jsonb(item));
end; $function$

CREATE OR REPLACE FUNCTION public.record_founder_activity(p_org uuid, p_record uuid, p_actor uuid, p_key uuid, p_details jsonb, p_acquisition uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.founder_research_records; e public.founder_activity_events; stamp timestamptz:=clock_timestamp();
begin
 select * into r from public.founder_research_records where organisation_id=p_org and id=p_record for update;
 if not found then raise exception 'Founder record not found'; end if;
 if p_details->>'activity_type'='promoted_to_acquisition' then
 if p_acquisition is null then raise exception 'Promotion requires an acquisition link'; end if;
 elsif p_acquisition is not null then raise exception 'Only promotion may carry an acquisition link'; end if;
 if p_acquisition is not null then
 if not exists(select 1 from public.acquisition_items where organisation_id=p_org and id=p_acquisition) then raise exception 'Invalid tenant acquisition link'; end if;
 if r.linked_acquisition_item_id is not null and r.linked_acquisition_item_id<>p_acquisition then raise exception 'Acquisition link changed'; end if;
 end if;
 if p_details->>'activity_type'='linked_gmail_evidence' then
 if nullif(btrim(p_details->>'gmail_message_id'),'') is null or nullif(btrim(p_details->>'gmail_thread_id'),'') is null then raise exception 'Both authoritative Gmail IDs required'; end if;
 elsif p_details->>'gmail_message_id' is not null or p_details->>'gmail_thread_id' is not null then raise exception 'Only Gmail evidence may carry Gmail IDs'; end if;
 select * into e from public.founder_activity_events where organisation_id=p_org and idempotency_key=p_key;
 if found then
 if e.research_record_id<>p_record or e.actor<>p_actor or e.receipt_details is distinct from p_details then raise exception 'idempotency_key_reused'; end if;
 return jsonb_build_object('duplicate',true,'id',e.id);
 end if;
 if p_acquisition is not null then
 update public.founder_research_records set linked_acquisition_item_id=p_acquisition,updated_at=stamp where id=p_record and organisation_id=p_org;
 end if;
 if p_details->>'gmail_message_id' is not null then
 if p_details->>'activity_type'<>'linked_gmail_evidence' or not exists(select 1 from public.email_conversation_messages where organisation_id=p_org and gmail_message_id=p_details->>'gmail_message_id' and gmail_thread_id=p_details->>'gmail_thread_id') then raise exception 'Existing tenant Gmail evidence required'; end if;
 select * into e from public.founder_activity_events where organisation_id=p_org and gmail_message_id=p_details->>'gmail_message_id';
 if found then
 if e.research_record_id<>p_record then raise exception 'Gmail evidence already linked to another Founder record; review identity'; end if;
 return jsonb_build_object('duplicate',true,'id',e.id);
 end if;
 end if;
 update public.founder_research_records set updated_at=stamp where id=p_record and organisation_id=p_org;
 insert into public.founder_activity_events(organisation_id,research_record_id,actor,activity_type,occurred_at,recorded_at,route,subject,message,gmail_message_id,gmail_thread_id,idempotency_key,receipt_details)
 values(p_org,p_record,p_actor,p_details->>'activity_type',case when p_details->>'time_status'='now' then stamp else nullif(p_details->>'occurred_at','')::timestamptz end,stamp,p_details->>'route',p_details->>'subject',p_details->>'message',p_details->>'gmail_message_id',p_details->>'gmail_thread_id',p_key,p_details) returning * into e;
 return jsonb_build_object('duplicate',false,'id',e.id);
end $function$

CREATE OR REPLACE FUNCTION public.record_linkedin_send_evidence(p_organisation_id uuid, p_actor uuid, p_table text, p_id uuid, p_revision bigint, p_key uuid, p_details jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare version bigint; previous jsonb; receipt jsonb; sent timestamptz; confirmed timestamptz := clock_timestamp(); next_stage text; sent_stage text; target public.growth_targets%rowtype; item public.inbox_items%rowtype; correction boolean := coalesce((p_details->>'correction')::boolean,false);
begin
 if p_actor is null or p_key is null or p_table not in ('growth_targets','inbox_items') or nullif(trim(p_details->>'message'),'') is null or length(p_details->>'message')>50000 or p_details->>'choice' not in ('now','today','historical','unknown','conversation') then raise exception 'invalid_send_evidence'; end if;
 sent := case when p_details->>'choice'='unknown' or p_details->>'choice'='conversation' and p_details->>'status'='unknown' then null when p_details->>'choice'='now' then coalesce((p_details->>'sentAt')::timestamptz,confirmed) else (p_details->>'sentAt')::timestamptz end;
 if not (p_details->>'choice'='unknown' or p_details->>'choice'='conversation' and p_details->>'status'='unknown') and (sent is null or sent>confirmed) then raise exception 'invalid_external_send_date'; end if;
 if p_details->>'choice'='conversation' and sent is not null and p_details->>'earliestOutboundConfirmed' is distinct from 'true' then raise exception 'earliest_outbound_confirmation_required'; end if;
 insert into public.lifecycle_revisions(organisation_id) values(p_organisation_id) on conflict do nothing;
 select revision into version from public.lifecycle_revisions where organisation_id=p_organisation_id for update;
 if p_table='growth_targets' then
 select * into target from public.growth_targets where organisation_id=p_organisation_id and id=p_id for update;
 if not found then raise exception 'record_not_found'; end if;
 previous:=target.manual_completion;
 if previous is null and target.source_type='lifecycle_connection_accepted' and target.stage<>'connection' then
 select manual_completion into previous from public.inbox_items where organisation_id=p_organisation_id and id::text=target.source_record_id and platform='linkedin' and kind='connection_accepted' and manual_completion->>'historical_send_date_status'='verified' and manual_completion->>'stage'='connection';
 end if;
 else
 select * into item from public.inbox_items where organisation_id=p_organisation_id and id=p_id for update;
 if not found or item.platform is distinct from 'linkedin' or item.kind is distinct from 'connection_accepted' then raise exception 'verified_acceptance_required'; end if;
 previous:=item.manual_completion;
 end if;
 if previous->>'key'=p_key::text or exists(select 1 from jsonb_array_elements(coalesce(previous->'history','[]')) r where r->>'key'=p_key::text) then return jsonb_build_object('duplicate',true); end if;
 if version is distinct from p_revision then raise exception 'stale_send_plan'; end if;
 if correction then
 if previous is null or nullif(trim(previous->>'key'),'') is null or nullif(trim(previous->>'actor'),'') is null or nullif(trim(previous->>'evidence'),'') is null or previous->>'message' is distinct from p_details->>'message' then raise exception 'original_receipt_required'; end if;
 if previous->>'stage' is distinct from 'connection' and (previous ? 'stage' or jsonb_array_length(coalesce(previous->'history','[]'))<>0) then raise exception 'first_send_classification_only'; end if;
 if p_table='growth_targets' and target.stage not in ('connection','day3_dm','day3_followup') then raise exception 'later_cadence_requires_review'; end if;
 else
 if p_table='inbox_items' and (previous is not null or item.status in ('replied','archived')) then raise exception 'already_contacted'; end if;
 if p_table='growth_targets' and target.stage='connection' and (previous is not null or target.last_action_at is not null) then raise exception 'already_contacted'; end if;
 end if;
 if p_table='growth_targets' and (target.status not in ('active','waiting') or target.replied_at is not null or coalesce(target.reply_status,'') not in ('','no_reply') or target.deal_stage in ('meeting','nurture','lost','closed','converted','won','engaged','opportunity')) then raise exception 'stronger_state'; end if;
 sent_stage:=case when correction or p_table='inbox_items' then 'connection' else p_details->>'sentStage' end;
 next_stage:=case sent_stage when 'connection' then 'day3_followup' when 'day3_followup' then 'day7_parity' when 'day7_parity' then 'day14_insight' when 'day14_insight' then 'day28_relevance' when 'day28_relevance' then 'day42_close' when 'day42_close' then 'parked' else null end;
 if next_stage is null then raise exception 'invalid_cadence_stage'; end if;
 if sent_stage='connection' and sent is not null then
 next_stage:=case when sent<=confirmed-interval '42 days' then 'day42_close' when sent<=confirmed-interval '28 days' then 'day28_relevance' when sent<=confirmed-interval '14 days' then 'day14_insight' when sent<=confirmed-interval '7 days' then 'day7_parity' else 'day3_followup' end;
 end if;
 receipt:=jsonb_build_object('key',p_key,'actor',p_actor,'completed_at',confirmed,'confirmed_at',confirmed,'recorded_at',confirmed,'sent_at',sent,'stage',sent_stage,'message',p_details->>'message','source',p_details->>'source','content_kind',case when p_details->>'choice'='conversation' then 'conversation_history_pasted' else 'single_outbound_message' end,'earliest_verified_outbound_at',case when p_details->>'choice'='conversation' then sent else null end,'date_basis',case when p_details->>'choice'='conversation' then 'User explicitly confirmed earliest outbound date; no dates inferred from pasted text' else 'User confirmed external send date' end,'evidence',case when p_details->>'choice'='conversation' then 'User explicitly confirmed pasted LinkedIn conversation history and earliest outbound date status; no individual message dates inferred.' else 'User explicitly confirmed the exact message and external LinkedIn send classification.' end,'correction_type',case when correction then 'first_send_classification' else 'manual_send_confirmation' end,'historical_send_date_status',case when sent is null then 'unknown' else 'verified' end,'timezone',p_details->>'timezone','sent_time_precision',p_details->>'precision','history',coalesce(previous->'history','[]') || case when previous is null then '[]'::jsonb else jsonb_build_array(previous-'history') end);
 if p_table='growth_targets' then
 update public.growth_targets set manual_completion=receipt,stage=next_stage,status=case when next_stage='parked' then 'parked' else 'active' end,last_action_at=sent,last_reply_text=p_details->>'message',first_outbound_at=case when sent_stage='connection' then sent else first_outbound_at end,first_outbound_text=case when sent_stage='connection' then p_details->>'message' else first_outbound_text end where organisation_id=p_organisation_id and id=p_id;
 else
 update public.inbox_items set manual_completion=receipt,status='replied',response_state='waiting_for_human',contacted_at=sent,last_replied_at=sent,last_reply_text=p_details->>'message',follow_up_at=null where organisation_id=p_organisation_id and id=p_id;
 end if;
 return jsonb_build_object('duplicate',false,'sentAt',sent,'confirmedAt',confirmed);
end; $function$

CREATE OR REPLACE FUNCTION public.record_manual_completion(p_organisation_id uuid, p_actor uuid, p_table text, p_id uuid, p_revision bigint, p_key uuid, p_completed_at timestamp with time zone, p_evidence text, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare version bigint; previous jsonb; receipt jsonb; item public.inbox_items%rowtype; target public.growth_targets%rowtype;
begin
 if p_table not in ('inbox_items','growth_targets') or p_key is null or p_actor is null or p_completed_at is null
 or p_completed_at > now() or nullif(trim(p_evidence),'') is null or length(p_evidence)>2000 or jsonb_typeof(p_patch) is distinct from 'object' then raise exception 'invalid_manual_receipt'; end if;
 insert into public.lifecycle_revisions(organisation_id) values(p_organisation_id) on conflict do nothing;
 insert into public.lifecycle_revisions(organisation_id) values(p_organisation_id) on conflict do nothing;
 select revision into version from public.lifecycle_revisions where organisation_id=p_organisation_id for update;
 if p_table='inbox_items' then
 -- Serialise against an already reserved Phase 4D delivery without changing its semantics.
 perform 1 from public.email_send_requests where organisation_id=p_organisation_id and inbox_item_id=p_id for update;
 select * into item from public.inbox_items where organisation_id=p_organisation_id and id=p_id for update;
 if not found then raise exception 'record_not_found'; end if;
 previous := item.manual_completion;
 else
 select * into target from public.growth_targets where organisation_id=p_organisation_id and id=p_id for update;
 if not found then raise exception 'record_not_found'; end if;
 previous := target.manual_completion;
 end if;
 if previous->>'key'=p_key::text or exists(select 1 from jsonb_array_elements(coalesce(previous->'history','[]'::jsonb)) r where r->>'key'=p_key::text) then return jsonb_build_object('duplicate',true); end if;
 if version is distinct from p_revision then raise exception 'stale_manual_plan'; end if;
 receipt := jsonb_build_object('key',p_key,'actor',p_actor,'completed_at',p_completed_at,'recorded_at',now(),'evidence',p_evidence,'message',p_patch->>'last_reply_text','stage',case when p_table='growth_targets' then case p_patch->>'stage' when 'day3_followup' then 'connection' when 'day7_parity' then 'day3_followup' when 'day14_insight' then 'day7_parity' when 'day28_relevance' then 'day14_insight' when 'day42_close' then 'day28_relevance' when 'parked' then 'day42_close' end else 'connection' end,
 'history',coalesce(previous->'history','[]'::jsonb) || case when previous is null then '[]'::jsonb else jsonb_build_array(previous-'history') end);
 if p_table='inbox_items' then
 if item.status in ('replied','archived') or previous is not null or item.email_delivery_status in ('approved','dispatching','sent')
 or exists(select 1 from public.email_send_requests where organisation_id=p_organisation_id and inbox_item_id=p_id and status in ('dispatching','accepted','sent'))
 then raise exception 'already_handled_or_delivery_uncertain'; end if;
 if p_patch-array['status','response_state','follow_up_at','last_replied_at','last_reply_text','contacted_at'] <> '{}'::jsonb
 or p_patch->>'status' is distinct from 'replied' or p_patch->>'response_state' not in ('engaged','waiting_for_human') then raise exception 'invalid_manual_patch'; end if;
 update public.inbox_items set status='replied',response_state=p_patch->>'response_state',follow_up_at=null,
 last_replied_at=p_completed_at,last_reply_text=p_patch->>'last_reply_text',
 contacted_at=case when kind='connection_accepted' then p_completed_at else contacted_at end,
 manual_completion=receipt where organisation_id=p_organisation_id and id=p_id;
 insert into public.response_item_events(organisation_id,inbox_item_id,actor_user_id,action,previous_state,new_state,note,idempotency_key)
 values(p_organisation_id,p_id,p_actor,'manual_complete',item.response_state,p_patch->>'response_state',p_evidence,p_key);
 else
 if target.status is distinct from 'active' or target.replied_at is not null or coalesce(target.reply_status,'') not in ('','no_reply')
 then raise exception 'cadence_not_actionable'; end if;
 if p_patch-array['stage','status','last_action_at','last_reply_text'] <> '{}'::jsonb or p_patch->>'stage' is null
 or p_patch->>'stage'=target.stage or p_patch->>'status' not in ('active','parked') then raise exception 'invalid_manual_patch'; end if;
 update public.growth_targets set stage=p_patch->>'stage',status=p_patch->>'status',last_action_at=p_completed_at,manual_completion=receipt,
 last_reply_text=p_patch->>'last_reply_text',
 first_outbound_at=case when target.stage='connection' then coalesce(target.first_outbound_at,p_completed_at) else target.first_outbound_at end,
 first_outbound_text=case when target.stage='connection' then coalesce(target.first_outbound_text,p_patch->>'last_reply_text') else target.first_outbound_text end
 where organisation_id=p_organisation_id and id=p_id;
 end if;
 return jsonb_build_object('duplicate',false,'completedAt',p_completed_at);
end; $function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
 new.updated_at = now();
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.track_lifecycle_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 tenant uuid;
begin
 if tg_op = 'DELETE' then
 tenant := old.organisation_id;
 else
 tenant := new.organisation_id;
 end if;

 if tenant is not null then
 insert into public.lifecycle_revisions(organisation_id, revision)
 values(tenant, 1)
 on conflict(organisation_id)
 do update set revision = lifecycle_revisions.revision + 1;
 end if;

 if tg_op = 'UPDATE'
 and old.organisation_id is distinct from new.organisation_id
 and old.organisation_id is not null then
 insert into public.lifecycle_revisions(organisation_id, revision)
 values(old.organisation_id, 1)
 on conflict(organisation_id)
 do update set revision = lifecycle_revisions.revision + 1;
 end if;

 if tg_op = 'DELETE' then
 return old;
 end if;

 return new;
end;
$function$

CREATE OR REPLACE FUNCTION storage.enforce_bucket_name_length()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
 if length(new.name) > 100 then
 raise exception 'bucket name "%" is too long (% characters). Max is 100.', new.name, length(new.name);
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION storage.protect_bucket_control_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 configuration_changed boolean;
BEGIN
 IF TG_OP = 'INSERT' THEN
 IF NEW.lifecycle_configuration IS NOT NULL
 OR NEW.lifecycle_configuration_generation IS NOT NULL THEN
 IF NOT pg_has_role(current_user, TG_ARGV[0], 'MEMBER') THEN
 RAISE EXCEPTION 'only members of the configured storage service role may insert lifecycle policy state'
 USING ERRCODE = '42501',
 HINT = format(
 'Insert with both lifecycle columns NULL and configure lifecycle through the Storage API afterward, or insert as a member of %I.',
 TG_ARGV[0]
 );
 END IF;
 END IF;

 RETURN NEW;
 END IF;

 configuration_changed =
 OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration
 OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation;

 IF NOT configuration_changed THEN
 RETURN NEW;
 END IF;

 IF NEW.type IS DISTINCT FROM 'STANDARD' THEN
 RAISE EXCEPTION 'bucket versioning and lifecycle controls require a Standard bucket'
 USING ERRCODE = '0A000';
 END IF;

 IF NEW.lifecycle_configuration IS NULL
 AND NEW.lifecycle_configuration_generation IS NULL THEN
 RETURN NEW;
 END IF;

 IF NEW.lifecycle_configuration IS NULL
 OR NEW.lifecycle_configuration_generation IS NULL
 OR OLD.lifecycle_configuration IS NOT DISTINCT FROM NEW.lifecycle_configuration
 OR OLD.lifecycle_configuration_generation IS NOT DISTINCT FROM NEW.lifecycle_configuration_generation THEN
 RAISE EXCEPTION 'a changed lifecycle policy requires a new non-null generation'
 USING ERRCODE = '22023';
 END IF;

 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text)
 RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
 v_peek_name TEXT;
 v_current RECORD;
 v_common_prefix TEXT;
 v_delimiter CONSTANT TEXT := '/';

 -- Configuration
 v_limit INT;
 v_prefix TEXT;
 v_prefix_lower TEXT;
 v_prefix_len INT;
 v_prefix_start INT;
 v_combined_levels INT;
 v_is_asc BOOLEAN;
 v_order_by TEXT;
 v_sort_order TEXT;
 v_upper_bound TEXT;
 v_file_batch_size INT;
 v_version_filter TEXT;
 v_multi_row BOOLEAN;

 -- Dynamic SQL for batch query only
 v_batch_query TEXT;
 v_delete_marker_peek_query TEXT;
 v_delete_marker_peek_query_strict TEXT;

 -- Seek state
 v_next_seek TEXT;
 v_next_seek_at TIMESTAMPTZ;
 v_next_seek_version TEXT;
 v_next_seek_strict BOOLEAN := false;
 v_count INT := 0;
 v_skipped INT := 0;
 v_previous_seek TEXT;
 v_previous_seek_at TIMESTAMPTZ;
 v_previous_seek_version TEXT;
 v_previous_count INT;
 v_previous_skipped INT;
BEGIN
 -- ========================================================================
 -- INITIALIZATION
 -- ========================================================================
 v_limit := LEAST(coalesce(limits, 100), 1500);
 v_prefix := coalesce(prefix, '') || coalesce(search, '');
 v_prefix_lower := lower(v_prefix);
 v_prefix_len := length(coalesce(prefix, ''));
 v_prefix_start := coalesce(array_length(string_to_array(coalesce(prefix, ''), v_delimiter), 1), 1);
 v_combined_levels := coalesce(array_length(string_to_array(v_prefix, v_delimiter), 1), 1);
 v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';
 v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);
 v_next_seek_at := NULL;
 v_next_seek_version := '';

 -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a
 -- bare NOT IN check silently leaves an explicit NULL argument unreset.
 noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');
 delete_markers := COALESCE(delete_markers, 'exclude');
 IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN
 noncurrent_versions := 'exclude';
 END IF;
 IF delete_markers NOT IN ('exclude', 'only', 'include') THEN
 delete_markers := 'exclude';
 END IF;

 v_multi_row := noncurrent_versions IN ('only', 'include');

 v_version_filter := '';
 IF noncurrent_versions = 'exclude' THEN
 v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';
 ELSIF noncurrent_versions = 'only' THEN
 v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';
 END IF;
 IF delete_markers = 'exclude' THEN
 v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';
 ELSIF delete_markers = 'only' THEN
 v_version_filter := v_version_filter || ' AND o.is_delete_marker';
 END IF;

 -- Validate sort column
 CASE lower(coalesce(sortcolumn, 'name'))
 WHEN 'name' THEN v_order_by := 'name';
 WHEN 'updated_at' THEN v_order_by := 'updated_at';
 WHEN 'created_at' THEN v_order_by := 'created_at';
 WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';
 ELSE v_order_by := 'name';
 END CASE;

 v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;

 -- ========================================================================
 -- NON-NAME SORTING: Use path_tokens approach
 -- ========================================================================
 IF v_order_by != 'name' THEN
 RETURN QUERY EXECUTE format(
 $sql$
 WITH folders AS (
 SELECT array_to_string(path_tokens[$1:$2], '/') AS folder
 FROM storage.objects
 WHERE objects.name ILIKE $3 || '%%'
 AND bucket_id = $4
 AND array_length(objects.path_tokens, 1) <> $2
 AND ($7 != 'exclude' OR objects.archived_at IS NULL)
 AND ($7 != 'only' OR objects.archived_at IS NOT NULL)
 AND ($8 != 'exclude' OR NOT objects.is_delete_marker)
 AND ($8 != 'only' OR objects.is_delete_marker)
 GROUP BY folder
 ORDER BY folder %s
 )
 (SELECT folder AS "name",
 NULL::uuid AS id,
 NULL::timestamptz AS updated_at,
 NULL::timestamptz AS created_at,
 NULL::timestamptz AS last_accessed_at,
 NULL::jsonb AS metadata,
 NULL::text AS version,
 NULL::timestamptz AS archived_at,
 NULL::boolean AS is_delete_marker,
 NULL::boolean AS is_versioned FROM folders)
 UNION ALL
 (SELECT array_to_string(path_tokens[$1:$2], '/') AS "name",
 id, updated_at, created_at, last_accessed_at, metadata,
 version, archived_at, is_delete_marker, is_versioned
 FROM storage.objects
 WHERE objects.name ILIKE $3 || '%%'
 AND bucket_id = $4
 AND array_length(objects.path_tokens, 1) = $2
 AND ($7 != 'exclude' OR objects.archived_at IS NULL)
 AND ($7 != 'only' OR objects.archived_at IS NOT NULL)
 AND ($8 != 'exclude' OR NOT objects.is_delete_marker)
 AND ($8 != 'only' OR objects.is_delete_marker)
 -- name, then version, as tiebreaks so two versions of the same
 -- key tying on the sort column still sort deterministically
 ORDER BY %I %s, name COLLATE "C" %s, COALESCE(version, '') %s)
 LIMIT $5 OFFSET $6
 $sql$, v_sort_order, v_order_by, v_sort_order, v_sort_order, v_sort_order
 ) USING v_prefix_start, v_combined_levels, v_prefix, bucketname, v_limit, offsets, noncurrent_versions, delete_markers;
 RETURN;
 END IF;

 -- ========================================================================
 -- NAME SORTING: Hybrid skip-scan with batch optimization
 -- ========================================================================

 -- Calculate upper bound for prefix filtering
 IF v_prefix_lower = '' THEN
 v_upper_bound := NULL;
 ELSIF right(v_prefix_lower, 1) = v_delimiter THEN
 v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);
 ELSE
 v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);
 END IF;

 -- Build a resume-safe batch query. The exact-name branch returns remaining
 -- versions after the current (archived_at, version) boundary; the strict
 -- name branch returns subsequent keys. UNION ALL keeps both predicates
 -- independently indexable.
 IF v_is_asc THEN
 IF v_upper_bound IS NOT NULL THEN
 v_batch_query := 'SELECT * FROM (' ||
 '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
 'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
 v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
 '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
 'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" > $2 AND lower(o.name) COLLATE "C" < $3' || v_version_filter ||
 ' ORDER BY lower(o.name) COLLATE "C" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
 ') sub ORDER BY lower(sub.name) COLLATE "C" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
 ELSE
 v_batch_query := 'SELECT * FROM (' ||
 '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
 'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
 v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
 '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
 'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" > $2' || v_version_filter ||
 ' ORDER BY lower(o.name) COLLATE "C" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
 ') sub ORDER BY lower(sub.name) COLLATE "C" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
 END IF;
 ELSE
 IF v_upper_bound IS NOT NULL THEN
 v_batch_query := 'SELECT * FROM (' ||
 '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
 'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
 v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
 '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
 'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 AND lower(o.name) COLLATE "C" >= $3' || v_version_filter ||
 ' ORDER BY lower(o.name) COLLATE "C" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
 ') sub ORDER BY lower(sub.name) COLLATE "C" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
 ELSE
 v_batch_query := 'SELECT * FROM (' ||
 '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
 'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
 v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
 '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
 'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2' || v_version_filter ||
 ' ORDER BY lower(o.name) COLLATE "C" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
 ') sub ORDER BY lower(sub.name) COLLATE "C" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
 END IF;
 END IF;

 -- Keep the delete-marker predicate literal so the cached generic
 -- plan can use idx_objects_delete_markers during the main-loop peek.
 IF delete_markers = 'only' THEN
 IF v_multi_row THEN
 v_delete_marker_peek_query :=
 'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';
 ELSIF v_is_asc THEN
 -- Two separate literal query strings, not one gated by a bound
 -- boolean: folding "$n AND op1 OR NOT $n AND op2" into a single
 -- query defeats the generic plan's ability to push either
 -- comparison into the index. Branching in PL/pgSQL control flow
 -- instead keeps each query's index condition intact.
 v_delete_marker_peek_query :=
 'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||
 'AND lower(o.name) COLLATE "C" >= $2' ||
 CASE WHEN v_upper_bound IS NOT NULL
 THEN ' AND lower(o.name) COLLATE "C" < $3'
 ELSE ''
 END ||
 v_version_filter ||
 ' ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1';
 -- Strict variant: used once the single-row ASC batch advance
 -- (below) has left v_next_seek pointing at the last row already
 -- emitted, so a plain >= would re-match it forever.
 v_delete_marker_peek_query_strict :=
 'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||
 'AND lower(o.name) COLLATE "C" > $2' ||
 CASE WHEN v_upper_bound IS NOT NULL
 THEN ' AND lower(o.name) COLLATE "C" < $3'
 ELSE ''
 END ||
 v_version_filter ||
 ' ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1';
 ELSE
 v_delete_marker_peek_query :=
 'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||
 'AND lower(o.name) COLLATE "C" < $2' ||
 CASE WHEN v_upper_bound IS NOT NULL
 THEN ' AND lower(o.name) COLLATE "C" >= $3'
 ELSE ''
 END ||
 v_version_filter ||
 ' ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1';
 END IF;
 END IF;

 -- Initialize seek position
 IF v_is_asc THEN
 v_next_seek := v_prefix_lower;
 ELSE
 -- DESC performs one specialized initial seek so partial current-version
 -- and delete-marker indexes remain available.
 EXECUTE format(
 'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1',
 CASE WHEN v_upper_bound IS NOT NULL
 THEN ' AND lower(o.name) COLLATE "C" >= $2 AND lower(o.name) COLLATE "C" < $3'
 ELSE ''
 END,
 v_version_filter
 )
 INTO v_peek_name
 USING bucketname, v_prefix_lower, v_upper_bound;

 IF v_peek_name IS NOT NULL THEN
 v_next_seek := lower(v_peek_name) || v_delimiter;
 ELSE
 RETURN;
 END IF;
 END IF;

 -- ========================================================================
 -- MAIN LOOP: Hybrid peek-then-batch algorithm
 -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch and
 -- the delete-marker-only path
 -- ========================================================================
 LOOP
 EXIT WHEN v_count >= v_limit;

 v_previous_seek := v_next_seek;
 v_previous_seek_at := v_next_seek_at;
 v_previous_seek_version := v_next_seek_version;
 v_previous_count := v_count;
 v_previous_skipped := v_skipped;

 -- STEP 1: PEEK
 v_peek_name := NULL;
 IF delete_markers = 'only' THEN
 EXECUTE CASE WHEN v_next_seek_strict
 THEN v_delete_marker_peek_query_strict
 ELSE v_delete_marker_peek_query
 END
 INTO v_peek_name
 USING bucketname, v_next_seek,
 CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END,
 1, v_next_seek_at, v_next_seek_version;
 ELSIF v_multi_row AND v_next_seek_at IS NOT NULL THEN
 SELECT o.name INTO v_peek_name
 FROM storage.objects o
 WHERE o.bucket_id = bucketname
 AND lower(o.name) COLLATE "C" = v_next_seek
 AND (COALESCE(o.archived_at, 'infinity'::timestamptz) < v_next_seek_at
 OR (COALESCE(o.archived_at, 'infinity'::timestamptz) = v_next_seek_at
 AND COALESCE(o.version, '') > v_next_seek_version))
 AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
 AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 AND (delete_markers != 'only' OR o.is_delete_marker)
 ORDER BY COALESCE(o.archived_at, 'infinity'::timestamptz) DESC,
 COALESCE(o.version, '') ASC
 LIMIT 1;

 -- The current key is exhausted. Clear its version boundary and
 -- make the following ASC name peek strict. Appending '/' is not a
 -- valid lexical successor because keys ending in characters such
 -- as '!' sort between the exhausted name and name || '/'.
 IF v_peek_name IS NULL THEN
 IF v_is_asc THEN
 v_next_seek_strict := true;
 END IF;
 v_next_seek_at := NULL;
 v_next_seek_version := '';
 END IF;
 END IF;

 -- Single-row mode is always noncurrent_versions='exclude'. Keep the
 -- current-row predicate literal so generic plans use the current index.
 IF delete_markers != 'only' AND v_peek_name IS NULL AND NOT v_multi_row THEN
 IF v_is_asc THEN
 IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
 AND o.archived_at IS NULL
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
 ELSIF v_next_seek_strict THEN
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek
 AND o.archived_at IS NULL
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
 ELSIF v_upper_bound IS NOT NULL THEN
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
 AND o.archived_at IS NULL
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
 ELSE
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
 AND o.archived_at IS NULL
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
 END IF;
 ELSIF v_upper_bound IS NOT NULL THEN
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
 AND o.archived_at IS NULL
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
 ELSE
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
 AND o.archived_at IS NULL
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
 END IF;
 ELSIF delete_markers != 'only' AND v_peek_name IS NULL AND v_is_asc THEN
 IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
 AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
 AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 AND (delete_markers != 'only' OR o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
 ELSIF v_next_seek_strict THEN
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek
 AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
 AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 AND (delete_markers != 'only' OR o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
 ELSIF v_upper_bound IS NOT NULL THEN
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
 AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
 AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 AND (delete_markers != 'only' OR o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
 ELSE
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
 AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
 AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 AND (delete_markers != 'only' OR o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
 END IF;
 ELSIF delete_markers != 'only' AND v_peek_name IS NULL THEN
 IF v_upper_bound IS NOT NULL THEN
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
 AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
 AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 AND (delete_markers != 'only' OR o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
 ELSE
 SELECT o.name INTO v_peek_name FROM storage.objects o
 WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
 AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
 AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
 AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
 AND (delete_markers != 'only' OR o.is_delete_marker)
 ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
 END IF;
 END IF;

 EXIT WHEN v_peek_name IS NULL;

 -- If the peek landed on a different key than we were tracking, any
 -- version boundary belongs to the OLD key and must not leak into the
 -- new one - e.g. the deleteMarkers='only' peek doesn't know or care
 -- whether it's continuing the same key or jumping to a new one, so
 -- it never clears these itself.
 IF lower(v_peek_name) IS DISTINCT FROM v_next_seek THEN
 v_next_seek_at := NULL;
 v_next_seek_version := '';
 END IF;

 -- The peek is authoritative for the next key to process. This is
 -- especially important after exhausting a multi-version key: the
 -- version boundary has been cleared, so executing the batch against
 -- a stale v_next_seek would replay every version of that old key.
 v_next_seek := lower(v_peek_name);
 v_next_seek_strict := false;

 -- STEP 2: Check if this is a FOLDER or FILE
 v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);

 IF v_common_prefix IS NOT NULL THEN
 -- FOLDER: Handle offset, emit if needed, skip to next folder
 IF v_skipped < offsets THEN
 v_skipped := v_skipped + 1;
 ELSE
 name := substring(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter) from v_prefix_len + 1);
 id := NULL;
 updated_at := NULL;
 created_at := NULL;
 last_accessed_at := NULL;
 metadata := NULL;
 version := NULL;
 archived_at := NULL;
 is_delete_marker := NULL;
 is_versioned := NULL;
 RETURN NEXT;
 v_count := v_count + 1;
 END IF;

 -- Advance seek past the folder range
 IF v_is_asc THEN
 v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);
 ELSE
 v_next_seek := lower(v_common_prefix);
 END IF;
 v_next_seek_at := NULL;
 v_next_seek_version := '';
 ELSE
 -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
 -- For ASC: upper_bound is the exclusive upper limit (< condition)
 -- For DESC: prefix_lower is the inclusive lower limit (>= condition)
 FOR v_current IN EXECUTE v_batch_query
 USING bucketname, v_next_seek,
 CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size,
 v_next_seek_at, v_next_seek_version
 LOOP
 v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);

 IF v_common_prefix IS NOT NULL THEN
 -- Hit a folder: exit batch, let peek handle it. Reset
 -- strict mode too - it may have been set by an earlier
 -- row in this same batch (see the single-row ASC advance
 -- below), and v_next_seek here is the folder-triggering
 -- row's own name, which the next peek must find inclusively.
 v_next_seek := CASE
 WHEN v_is_asc THEN lower(v_current.name)
 ELSE lower(v_current.name) || v_delimiter
 END;
 v_next_seek_at := NULL;
 v_next_seek_version := '';
 v_next_seek_strict := false;
 EXIT;
 END IF;

 -- Handle offset skipping
 IF v_skipped < offsets THEN
 v_skipped := v_skipped + 1;
 ELSE
 -- Emit file
 name := substring(v_current.name from v_prefix_len + 1);
 id := v_current.id;
 updated_at := v_current.updated_at;
 created_at := v_current.created_at;
 last_accessed_at := v_current.last_accessed_at;
 metadata := v_current.metadata;
 version := v_current.version;
 archived_at := v_current.archived_at;
 is_delete_marker := v_current.is_delete_marker;
 is_versioned := v_current.is_versioned;
 RETURN NEXT;
 v_count := v_count + 1;
 END IF;

 -- Multi-row mode must remain on this key until all of its
 -- versions have crossed the internal batch boundary.
 IF v_multi_row THEN
 v_next_seek := lower(v_current.name);
 v_next_seek_at := COALESCE(v_current.archived_at, 'infinity'::timestamptz);
 v_next_seek_version := COALESCE(v_current.version, '');
 ELSIF v_is_asc THEN
 -- Appending the delimiter as a fake lexical successor would
 -- skip a real key like `name || '!'` (or any character
 -- sorting below the delimiter), which sorts between `name`
 -- and `name || delimiter`. Track the real name and mark the
 -- next comparison strict instead - same fix as the
 -- exhausted-key case above.
 v_next_seek := lower(v_current.name);
 v_next_seek_strict := true;
 ELSE
 v_next_seek := lower(v_current.name);
 END IF;

 EXIT WHEN v_count >= v_limit;
 END LOOP;
 END IF;

 IF v_count = v_previous_count
 AND v_skipped = v_previous_skipped
 AND v_next_seek IS NOT DISTINCT FROM v_previous_seek
 AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at
 AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN
 RAISE EXCEPTION 'storage.search made no progress at seek (%, %, %)',
 v_next_seek, v_next_seek_at, v_next_seek_version;
 END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION storage.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 NEW.updated_at = now();
 RETURN NEW; 
END;
$function$
